                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[250%] h-6 bg-black -rotate-45 animate-slash-draw z-10 border-y-2 border-cyan-400 shadow-[0_0_50px_rgba(34,211,238,1)]"></div>
                    <div className="absolute inset-0 bg-cyan-500/10 animate-glitch mix-blend-color-dodge z-20"></div>
                    <div className="absolute w-[100px] h-[100px] rounded-full border-[20px] border-cyan-200 animate-shockwave z-20 opacity-0"></div>
                </>
            )}

            {hitVfx === 'revive' && (
               <div className="absolute inset-0 bg-emerald-500/20 animate-flash mix-blend-overlay"></div>
            )}
        </div>
      )}

      <div className={`relative w-full h-full flex items-center justify-between px-8 animate-in fade-in z-10 max-w-4xl mx-auto ${hitVfx === 'plus-ultra' ? 'animate-intense-shake' : ''}`}>

          <div className={`relative transition-all duration-500 ease-out z-20 ${isAttacking ? 'translate-x-32 scale-110 rotate-3' : (isDead ? 'scale-95 grayscale contrast-125' : 'animate-breathe')}`}>

              {isDead && (
                  <div className="absolute -top-12 left-1/2 -translate-x-1/2 w-48 text-center z-50 animate-in zoom-in duration-500 pointer-events-none">
                       <h2 className="text-xl font-serif font-bold text-red-600 tracking-widest drop-shadow-[0_2px_4px_rgba(0,0,0,1)] animate-pulse" style={{ textShadow: '0 0 10px rgba(220, 38, 38, 0.8)' }}>
                           YOU DIED
                       </h2>
                       <div className="h-px w-full bg-gradient-to-r from-transparent via-red-600 to-transparent mt-1"></div>
                  </div>
              )}

              {(isDead || hitVfx === 'revive') && (
                  <div className="absolute -bottom-20 left-1/2 w-48 h-48 pointer-events-none z-10" 
                       style={{ transform: 'translateX(-50%) rotateX(75deg)' }}>
                      <div className="w-full h-full border-[3px] border-emerald-500/60 rounded-full animate-spin-slow shadow-[0_0_20px_rgba(16,185,129,0.4)] flex items-center justify-center">
                           <div className="w-[80%] h-[80%] border-2 border-emerald-400/40 rounded-full border-dashed animate-reverse-spin"></div>
                           <div className="w-[40%] h-[40%] bg-emerald-500/20 rounded-full blur-md animate-pulse"></div>
                      </div>
                  </div>
              )}

              {(isDead || hitVfx === 'revive') && (
                  <div className="absolute inset-0 pointer-events-none z-40 overflow-visible">
                      {[...Array(8)].map((_, i) => (
                          <div 
                              key={`mote-${i}`}
                              className="absolute bottom-0 left-1/2 bg-emerald-300 w-1 h-1 rounded-full animate-float-up blur-[1px]"
                              style={{
                                  marginLeft: `${(Math.random() * 60) - 30}px`,
                                  animationDuration: `${1.5 + Math.random()}s`,
                                  animationDelay: `${Math.random()}s`,
                                  opacity: 0.7
                              }}
                          />
                      ))}

                      {[...Array(4)].map((_, i) => (
                          <div 
                              key={`cross-${i}`}
                              className="absolute bottom-0 left-1/2 text-emerald-400 text-xs font-bold animate-float-up"
                              style={{
                                  marginLeft: `${(Math.random() * 50) - 25}px`,
                                  animationDuration: `${2 + Math.random()}s`,
                                  animationDelay: `${Math.random() * 1.5}s`,
                                  textShadow: '0 0 5px rgba(16, 185, 129, 0.8)'
                              }}
                          >+</div>
                      ))}
                  </div>
              )}

              <div className={`w-28 h-28 sm:w-36 sm:h-36 rounded-xl border-4 ${isDead ? 'border-red-900 shadow-[0_0_50px_rgba(220,38,38,0.2)]' : 'border-slate-600'} bg-slate-800 overflow-hidden shadow-2xl relative group ring-2 ring-black/50 transition-all duration-500 z-20 ${isDead ? 'rotate-[-5deg] translate-y-4' : ''} ${isUndying ? 'ring-4 ring-yellow-400 shadow-[0_0_30px_rgba(250,204,21,0.5)]' : ''}`}>
                  <img src={userAvatar} className="w-full h-full object-cover pixel-art" alt="Hero" />

                  {isDead && (
                      <div className="absolute inset-0 opacity-50 mix-blend-screen animate-pulse" style={{ backgroundImage: `url(${userAvatar})`, backgroundSize: 'cover', transform: 'translateY(-10px) scale(1.1)', filter: 'blur(4px) grayscale(100%)' }}></div>
                  )}

                  <div className={`absolute inset-0 shadow-[inset_0_0_20px_rgba(168,85,247,0.4)] mix-blend-overlay ${isDead ? 'hidden' : ''}`}></div>
                  {isUndying && <div className="absolute inset-0 bg-yellow-500/20 animate-pulse mix-blend-overlay z-30 pointer-events-none"></div>}
                  {isDead && <div className="absolute inset-0 bg-red-900/20 mix-blend-multiply"></div>}
              </div>

              {isDead && (
                  <div className="absolute -bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center justify-center z-50 animate-in fade-in zoom-in duration-300">
                      <div className="relative w-16 h-1.5 bg-slate-900/80 rounded-full border border-emerald-500/30 shadow-[0_0_10px_rgba(16,185,129,0.3)] overflow-hidden">
                          <div 
                              className="h-full bg-gradient-to-r from-emerald-500 via-teal-400 to-white/80 animate-pulse relative"
                              style={{ width: `${(playerHp / playerMaxHp) * 100}%`, transition: 'width 0.3s ease-out' }}
                          >
                              <div className="absolute inset-0 bg-white/40 animate-shimmer"></div>
                          </div>
                      </div>
                      <span className="text-[9px] font-mono font-bold text-emerald-300 mt-1 drop-shadow-md tracking-wider animate-pulse">
                          {Math.floor((playerHp / playerMaxHp) * 100)}%
                      </span>
                  </div>
              )}

              {!isDead && (
                 <div className="absolute -bottom-5 left-1/2 -translate-x-1/2 w-32 z-50 pointer-events-none">
                     <div className="flex justify-center mb-1 h-4">
                         {isPlayerStunned && <span className="text-[9px] font-bold text-yellow-400 animate-pulse bg-black/50 px-1 rounded border border-yellow-500/50">STUNNED</span>}
                         {isUndying && <span className="text-[9px] font-bold text-yellow-400 animate-pulse bg-black/50 px-1 rounded border border-yellow-500/50 ml-1">UNDYING</span>}
                     </div>
                     <div className="h-3 bg-slate-950 rounded-full border border-emerald-900/50 relative overflow-hidden shadow-lg ring-1 ring-black/50 mb-1">
                         <div 
                             className={`h-full transition-all duration-300 ease-out relative ${playerHp < playerMaxHp * 0.3 ? 'bg-gradient-to-r from-red-600 to-red-500' : 'bg-gradient-to-r from-emerald-600 via-emerald-500 to-teal-500'}`} 
                             style={{ width: `${(playerHp / playerMaxHp) * 100}%` }}
                         ></div>
                         <div className="absolute inset-0 flex items-center justify-center text-[8px] font-mono font-bold text-white/90 tracking-widest drop-shadow-md z-10">
                             {Math.floor(playerHp)} / {Math.floor(playerMaxHp)}
                         </div>
                     </div>
                     <div className="h-1.5 bg-slate-950 rounded-full border border-blue-900/50 relative overflow-hidden shadow">
                         <div className="h-full bg-gradient-to-r from-blue-600 to-cyan-400 transition-all duration-100 ease-linear shadow-[0_0_8px_rgba(34,211,238,0.5)]" style={{ width: `${playerAttackGauge}%` }}></div>
                     </div>
                 </div>
              )}
              <div className="w-full h-4 bg-black/60 rounded-[100%] mt-[-10px] blur-md translate-y-4"></div>
          </div>

          <div className={`relative transition-all duration-150 ease-in-out z-20 ${targetHit ? 'animate-shake brightness-200 saturate-0' : (isEnemyAttacking ? '' : 'animate-idle')} ${isEnemyAttacking ? '-translate-x-40 scale-125 rotate-[-5deg] z-30' : ''} ${hitVfx === 'overcrit' || hitVfx === 'plus-ultra' ? 'contrast-200' : ''}`}>
              <div className="absolute -top-16 left-1/2 -translate-x-1/2 w-32 z-50 pointer-events-none">
                  <div className="flex justify-center mb-1 h-4">
                      {isEnemyStunned && <span className="text-[9px] font-bold text-yellow-400 animate-pulse bg-black/50 px-1 rounded border border-yellow-500/50">STUNNED</span>}
                  </div>
                  <div className="h-3 bg-slate-950 rounded-full border border-red-900/50 relative overflow-hidden shadow-lg shadow-red-900/20 mb-1">
                      <div className="h-full bg-gradient-to-r from-red-800 via-red-600 to-orange-600 transition-all duration-300 ease-out relative" style={{ width: `${(enemyHp / enemyMaxHp) * 100}%` }}></div>
                      <div className="absolute inset-0 flex items-center justify-center text-[8px] font-mono font-bold text-white/90 tracking-widest drop-shadow-md z-10">
                          {formatNumber(Math.floor(enemyHp))} / {formatNumber(Math.floor(enemyMaxHp))}
                      </div>
                  </div>
                  <div className="h-1.5 bg-slate-950 rounded-full border border-red-900/30 relative overflow-hidden shadow">
                      <div className="h-full bg-gradient-to-r from-red-900 to-orange-700 transition-all duration-100 ease-linear" style={{ width: `${enemyAttackGauge}%` }}></div>
                  </div>
              </div>

              {isEnemyAttacking && <div className="absolute inset-0 bg-red-500/20 blur-xl rounded-full scale-150 animate-ping"></div>}
              {targetHit && <div className="absolute inset-0 bg-white mix-blend-overlay rounded-full blur-xl opacity-60 animate-impact"></div>}
              {enemyMockText && <div className="absolute -top-32 right-0 bg-red-950/90 text-red-100 text-[10px] font-bold p-3 rounded-2xl rounded-br-none shadow-[0_0_20px_rgba(220,38,38,0.4)] z-50 animate-in zoom-in slide-in-from-bottom-2 w-max max-w-[180px] border border-red-500/50 whitespace-normal leading-tight">{enemyMockText}</div>}

              <div className="w-28 h-28 sm:w-36 sm:h-36 flex items-center justify-center relative">
                  <div className="w-full h-full relative flex items-center justify-center drop-shadow-[0_15px_25px_rgba(0,0,0,0.9)]">
                       <img src={enemyImage || 'https://raw.githubusercontent.com/damarude/PUBLICDAMAR/main/creatures/1-removebg-preview.png'} alt="Enemy" className="w-full h-full object-contain pixel-art" />
                  </div>
              </div>
              <div className="w-full h-4 bg-black/60 rounded-[100%] mt-[-10px] blur-md translate-y-4"></div>
          </div>
      </div>
    </>
  );
};

export const Timer: React.FC<TimerProps> = ({ 
    proficiency, autoStart, initialMode = 'STOPWATCH', lockMode = false, userAvatar, onComplete, onCancel, onUnlockAchievement,
    userLevel, bonusDmg, bonusHp, bonusHeal, bonusBlock, bonusStun, bonusBarrage, bonusCrit, critDmgMultiplier, attackSpeed, bonusGoldPct,
    streakMultiplier = 0, gearMultiplier = 0, libraryMultiplier = 0, speedMultiplier = 1, globalExpMultiplier = 1, extraPhrases, undieableChance = 0,
    musicEnabled, onToggleMusic, onSkipMusic
}) => {
  const [mode, setMode] = useState<TimerMode>(initialMode);
  const [isActive, setIsActive] = useState(autoStart);
  const [timeLeft, setTimeLeft] = useState(30 * 60); // Default 30m for timer
  const [elapsed, setElapsed] = useState(0);
  const [targetTime, setTargetTime] = useState(30); // Target minutes
  const [sessionNotes, setSessionNotes] = useState('');
  const [showNotes, setShowNotes] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [showMusicModal, setShowMusicModal] = useState(false);

  // Battle State
  const [enemyHp, setEnemyHp] = useState(100);
  const [enemyMaxHp, setEnemyMaxHp] = useState(100);
  const [playerHp, setPlayerHp] = useState(100);
  const [playerMaxHp, setPlayerMaxHp] = useState(100);
  const [playerAttackGauge, setPlayerAttackGauge] = useState(0);
  const [enemyAttackGauge, setEnemyAttackGauge] = useState(0);
  const [enemyLevel, setEnemyLevel] = useState(1);
  const [goldLooted, setGoldLooted] = useState(0);
  const [enemyImage, setEnemyImage] = useState('https://raw.githubusercontent.com/damarude/PUBLICDAMAR/main/creatures/1-removebg-preview.png');

  // Visual State
  const [bubbleText, setBubbleText] = useState<string | null>(null);
  const [damageNumbers, setDamageNumbers] = useState<DamageNumber[]>([]);
  const [goldDrops, setGoldDrops] = useState<GoldDrop[]>([]);
  const [slashEffect, setSlashEffect] = useState<'slash-1' | 'slash-2' | null>(null);
  const [isAttacking, setIsAttacking] = useState(false);
  const [isEnemyAttacking, setIsEnemyAttacking] = useState(false);
  const [targetHit, setTargetHit] = useState(false);
  const [enemyMockText, setEnemyMockText] = useState<string | null>(null);
  const [isDead, setIsDead] = useState(false);
  const [isUndying, setIsUndying] = useState(false);
  const [hitVfx, setHitVfx] = useState<'crit' | 'overcrit' | 'plus-ultra' | 'revive' | null>(null);
  const [isEnemyStunned, setIsEnemyStunned] = useState(false);
  const [isPlayerStunned, setIsPlayerStunned] = useState(false);

  // Setup Battle
  useEffect(() => {
      const baseHp = 33 + (userLevel * 5);
      const totalHp = Math.floor(baseHp * (1 + (bonusHp / 100)));
      setPlayerMaxHp(totalHp);
      setPlayerHp(totalHp);
      spawnNewEnemy(1);

      // Select random quote
      if (extraPhrases?.character && extraPhrases.character.length > 0) {
          const randomPhrase = extraPhrases.character[Math.floor(Math.random() * extraPhrases.character.length)];
          setBubbleText(randomPhrase);
          setTimeout(() => setBubbleText(null), 5000);
      } else {
          const quotes = TRAINING_QUOTES[proficiency.category] || TRAINING_QUOTES['General'];
          setBubbleText(quotes[Math.floor(Math.random() * quotes.length)]);
          setTimeout(() => setBubbleText(null), 5000);
      }
  }, []);

  const spawnNewEnemy = (lvl: number) => {
      const stats = getEnemyBaseHp(lvl);
      const scaling = getEnemyScaling(proficiency.level);
      const scaledHp = Math.floor(stats.hp * (1 + scaling.scale));

      setEnemyMaxHp(scaledHp);
      setEnemyHp(scaledHp);
      setEnemyLevel(lvl);
      setEnemyAttackGauge(0);
      setEnemyImage(`https://raw.githubusercontent.com/damarude/PUBLICDAMAR/main/creatures/${(lvl % 5) + 1}-removebg-preview.png`);

      if (Math.random() < 0.3) {
          const mocks = extraPhrases?.enemies && extraPhrases.enemies.length > 0 ? extraPhrases.enemies : ENEMY_MOCKS;
          setEnemyMockText(mocks[Math.floor(Math.random() * mocks.length)]);
          setTimeout(() => setEnemyMockText(null), 3000);
      }
  };

  // Timer Tick
  useEffect(() => {
      let interval: NodeJS.Timeout;
      if (isActive && !isDead) {
          interval = setInterval(() => {
              const tick = 1 * speedMultiplier;
              if (mode === 'TIMER') {
                  setTimeLeft(prev => {
                      if (prev <= 1) {
                          setIsActive(false);
                          setShowNotes(true);
                          return 0;
                      }
                      return prev - tick;
                  });
              } else {
                  setElapsed(prev => prev + tick);
              }

              // Battle Logic Tick
              if (!isPlayerStunned) setPlayerAttackGauge(prev => Math.min(100, prev + (0.5 + (attackSpeed/50)) * speedMultiplier));
              if (!isEnemyStunned) setEnemyAttackGauge(prev => Math.min(100, prev + (0.3 + (enemyLevel * 0.01)) * speedMultiplier));

          }, 1000 / speedMultiplier);
      }
      return () => clearInterval(interval);
  }, [isActive, mode, attackSpeed, enemyLevel, speedMultiplier, isDead, isPlayerStunned, isEnemyStunned]);

  // Battle Events
  useEffect(() => {
      if (playerAttackGauge >= 100) {
          handlePlayerAttack();
          setPlayerAttackGauge(0);
      }
      if (enemyAttackGauge >= 100) {
          handleEnemyAttack();
          setEnemyAttackGauge(0);
      }
  }, [playerAttackGauge, enemyAttackGauge]);

  // Regeneration while dead
  useEffect(() => {
      if (isDead) {
          const interval = setInterval(() => {
              setPlayerHp(prev => {
                  const regen = playerMaxHp * (0.05 + (bonusHeal / 100)); // 5% base + bonus
                  const next = Math.min(playerMaxHp, prev + regen);
                  if (next >= playerMaxHp) {
                      setIsDead(false);
                      setHitVfx('revive');
                      setTimeout(() => setHitVfx(null), 1000);
                  }
                  return next;
              });
          }, 1000 / speedMultiplier);
          return () => clearInterval(interval);
      }
  }, [isDead, playerMaxHp, bonusHeal, speedMultiplier]);

  const addDamageNumber = (val: number | string, type: DamageNumber['type']) => {
      const id = Date.now() + Math.random();
      setDamageNumbers(prev => [...prev, { 
          id, 
          value: val, 
          type, 
          x: 40 + Math.random() * 20, 
          y: 40 + Math.random() * 20 
      }]);
      setTimeout(() => setDamageNumbers(prev => prev.filter(d => d.id !== id)), 1000);
  };

  const handlePlayerAttack = () => {
      setIsAttacking(true);
      setTimeout(() => setIsAttacking(false), 200);

      // Multi-hit logic (Barrage)
      const hits = 1 + (Math.random() * 100 < bonusBarrage ? 1 : 0);

      for (let i = 0; i < hits; i++) {
          setTimeout(() => {
              // Calculate Damage
              let dmg = 1 + (userLevel * 0.2) + bonusDmg;
              let isCrit = Math.random() * 100 < bonusCrit;
              if (isCrit) {
                  dmg *= critDmgMultiplier;
                  setHitVfx(dmg > 50 ? 'overcrit' : 'crit');
                  if (dmg > 100) setHitVfx('plus-ultra');
                  setTimeout(() => setHitVfx(null), 500);
                  if (onUnlockAchievement) onUnlockAchievement('a22');
                  if (dmg > 500 && onUnlockAchievement) onUnlockAchievement('a44');
              }

              // Stun Logic
              if (Math.random() * 100 < bonusStun) {
                  setIsEnemyStunned(true);
                  addDamageNumber("STUN", 'stun');
                  setTimeout(() => setIsEnemyStunned(false), 3000);
              }

              setEnemyHp(prev => {
                  const newHp = Math.max(0, prev - dmg);
                  if (newHp === 0) {
                      handleEnemyDefeat();
                  }
                  return newHp;
              });

              setTargetHit(true);
              setSlashEffect(Math.random() > 0.5 ? 'slash-1' : 'slash-2');
              addDamageNumber(Math.floor(dmg), isCrit ? (dmg > 50 ? 'overcrit' : 'crit') : 'normal');
              audio.playCombatHit();

              setTimeout(() => {
                  setTargetHit(false);
                  setSlashEffect(null);
              }, 150);
          }, i * 200);
      }
  };

  const handleEnemyAttack = () => {
      setIsEnemyAttacking(true);
      setTimeout(() => setIsEnemyAttacking(false), 200);

      // Dodge/Block logic
      if (Math.random() * 100 < bonusBlock) {
          addDamageNumber("BLOCK", 'block');
          return;
      }

      const dmg = Math.floor((enemyLevel * 1.5) + 2);

      setPlayerHp(prev => {
          const newHp = Math.max(0, prev - dmg);
          if (newHp === 0) {
              // Undying Check
              if (Math.random() * 100 < undieableChance) {
                  setIsUndying(true);
                  addDamageNumber("UNDYING", 'heal');
                  setTimeout(() => setIsUndying(false), 2000);
                  if (onUnlockAchievement) onUnlockAchievement('a54');
                  return 1;
              }
              setIsDead(true);
              setEnemyMockText("Sit down.");
              setTimeout(() => setEnemyMockText(null), 2000);
          }
          return newHp;
      });
      addDamageNumber(dmg, 'enemy');
  };

  const handleEnemyDefeat = () => {
      const loot = Math.floor(getEnemyBaseHp(enemyLevel).baseGold * (1 + bonusGoldPct / 100));
      setGoldLooted(prev => prev + loot);

      // Visual Gold Drop
      const dropId = Date.now();
      setGoldDrops(prev => [...prev, { id: dropId, value: loot, x: 50, y: 50 }]);
      setTimeout(() => setGoldDrops(prev => prev.filter(d => d.id !== dropId)), 1000);

      // Respawn
      setTimeout(() => spawnNewEnemy(enemyLevel + 1), 1000);
  };

  const handleFinish = () => {
      setShowNotes(true);
      setIsActive(false);
  };

  const submitCompletion = () => {
      let duration = mode === 'TIMER' ? (targetTime * 60 - timeLeft) / 60 : elapsed / 60;
      if (mode === 'TIMER' && timeLeft <= 1) duration = targetTime; // Full completion

      const wasEarly = mode === 'TIMER' && timeLeft > 1;
      onComplete(duration, sessionNotes, goldLooted, wasEarly);
  };

  const formatTime = (seconds: number) => {
      const h = Math.floor(seconds / 3600);
      const m = Math.floor((seconds % 3600) / 60);
      const s = Math.floor(seconds % 60);
      if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
      return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  if (showNotes) {
      return (
          <div className="flex flex-col items-center justify-center h-full p-6 animate-in fade-in zoom-in-95">
              <div className="bg-slate-900 border-2 border-emerald-500 rounded-2xl p-8 w-full max-w-md shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 to-cyan-500"></div>

                  <div className="text-center mb-6">
                      <div className="w-16 h-16 bg-emerald-900/20 rounded-full flex items-center justify-center mx-auto mb-4 border border-emerald-500/50">
                          <CheckCircle2 className="text-emerald-500" size={32} />
                      </div>
                      <h2 className="text-2xl font-rpg font-bold text-white uppercase tracking-wider">Session Complete</h2>
                      <p className="text-slate-400 text-sm mt-1">Great work, {getRankName(userLevel)}.</p>
                  </div>

                  <div className="space-y-4 mb-6">
                      <div className="bg-slate-800 p-4 rounded-xl border border-slate-700">
                          <div className="flex justify-between mb-2">
                              <span className="text-slate-400 text-xs uppercase font-bold">Time Focused</span>
                              <span className="text-white font-mono font-bold">
                                  {mode === 'TIMER' ? formatTime(targetTime * 60 - timeLeft) : formatTime(elapsed)}
                              </span>
                          </div>
                          <div className="flex justify-between">
                              <span className="text-slate-400 text-xs uppercase font-bold">Gold Looted</span>
                              <span className="text-yellow-500 font-mono font-bold flex items-center gap-1">
                                  <Coins size={12}/> +{goldLooted}
                              </span>
                          </div>
                      </div>

                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Session Log (Optional)</label>
                          <textarea 
                              className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm text-white focus:border-emerald-500 outline-none resize-none h-24"
                              placeholder="What did you learn today?"
                              value={sessionNotes}
                              onChange={(e) => setSessionNotes(e.target.value)}
                          />
                      </div>
                  </div>

                  <button 
                      onClick={submitCompletion}
                      className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-sm"
                  >
                      Confirm <ArrowLeft size={16} className="rotate-180" />
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="flex flex-col h-full bg-slate-950 relative overflow-hidden">
        {showMusicModal && (
            <MusicControlModal 
                onClose={() => setShowMusicModal(false)} 
                isPlaying={musicEnabled}
                onToggle={onToggleMusic}
                onSkip={onSkipMusic}
            />
        )}
        {showSupport && <SupportModal onClose={() => setShowSupport(false)} />}

        {/* --- Top Bar --- */}
        <div className="flex items-center justify-between px-6 py-4 bg-slate-900/50 backdrop-blur-sm border-b border-slate-800 z-50">
            <button onClick={onCancel} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors border border-slate-700">
                <ArrowLeft size={20} />
            </button>
            <div className="flex flex-col items-center">
                <h2 className="text-sm font-bold text-white uppercase tracking-widest">{proficiency.name}</h2>
                <div className="flex items-center gap-2">
                    <span className="text-[10px] text-purple-400 font-bold px-1.5 py-0.5 rounded border border-purple-500/30 bg-purple-900/20">{mode} MODE</span>
                    {isActive && <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>}
                </div>
            </div>
            <div className="flex gap-2">
                <MusicPlayerWidget 
                    isPlaying={musicEnabled}
                    onToggle={onToggleMusic}
                    onSkip={onSkipMusic}
                    onOpenControl={() => setShowMusicModal(true)}
                />
            </div>
        </div>

        {/* --- Battle Area --- */}
        <div className="flex-1 relative overflow-hidden flex items-center justify-center">
            <LocalBattleScene 
                userAvatar={userAvatar}
                enemyImage={enemyImage}
                enemyHp={enemyHp}
                enemyMaxHp={enemyMaxHp}
                playerHp={playerHp}
                playerMaxHp={playerMaxHp}
                playerAttackGauge={playerAttackGauge}
                enemyAttackGauge={enemyAttackGauge}
                isDead={isDead}
                isUndying={isUndying}
                isAttacking={isAttacking}
                isEnemyAttacking={isEnemyAttacking}
                targetHit={targetHit}
                hitVfx={hitVfx}
                slashEffect={slashEffect}
                bubbleText={bubbleText}
                enemyMockText={enemyMockText}
                isEnemyStunned={isEnemyStunned}
                isPlayerStunned={isPlayerStunned}
                enableVFX={true}
            />

            {/* Damage Numbers Overlay */}
            {damageNumbers.map(d => (
                <div 
                    key={d.id}
                    className={`absolute text-xl font-black pointer-events-none animate-damage-float z-[60] ${
                        d.type === 'crit' ? 'text-yellow-400 text-3xl' :
                        d.type === 'overcrit' ? 'text-orange-500 text-4xl' :
                        d.type === 'plus-ultra' ? 'text-cyan-400 text-5xl' :
                        d.type === 'heal' ? 'text-green-400' :
                        d.type === 'enemy' ? 'text-red-500' :
                        d.type === 'block' ? 'text-blue-400' :
                        d.type === 'stun' ? 'text-yellow-200' :
                        'text-white'
                    }`}
                    style={{ left: `${d.x}%`, top: `${d.y}%`, textShadow: '0 2px 4px rgba(0,0,0,0.8)' }}
                >
                    {d.value}
                </div>
            ))}

            {/* Gold Drops Overlay */}
            {goldDrops.map(d => (
                <div 
                    key={d.id}
                    className="absolute z-[60] flex items-center gap-1 text-yellow-400 font-bold text-xl animate-float-up pointer-events-none"
                    style={{ left: `${d.x}%`, top: `${d.y}%` }}
                >
                    <Coins size={20} /> +{d.value}
                </div>
            ))}
        </div>

        {/* --- Bottom Controls --- */}
        <div className="bg-slate-900 border-t border-slate-800 p-6 z-50">
            <div className="flex flex-col items-center mb-6">
                <div className={`text-6xl font-mono font-bold tracking-widest mb-2 ${isActive ? 'text-white' : 'text-slate-500'}`} style={{ fontVariantNumeric: 'tabular-nums' }}>
                    {mode === 'TIMER' ? formatTime(timeLeft) : formatTime(elapsed)}
                </div>
                {mode === 'TIMER' && (
                    <div className="w-full max-w-md h-1.5 bg-slate-800 rounded-full overflow-hidden">
                        <div 
                            className="h-full bg-gradient-to-r from-purple-500 to-blue-500 transition-all duration-1000 ease-linear" 
                            style={{ width: `${(timeLeft / (targetTime * 60)) * 100}%` }} 
                        />
                    </div>
                )}
            </div>

            <div className="flex justify-center gap-6">
                {!lockMode && mode === 'TIMER' && !isActive && timeLeft === targetTime * 60 && (
                    <div className="flex items-center gap-2 bg-slate-800 rounded-lg p-1">
                        {[15, 30, 45, 60].map(m => (
                            <button 
                                key={m}
                                onClick={() => { setTargetTime(m); setTimeLeft(m * 60); }}
                                className={`px-3 py-1 rounded text-xs font-bold transition-all ${targetTime === m ? 'bg-purple-600 text-white' : 'text-slate-400 hover:text-white'}`}
                            >
                                {m}m
                            </button>
                        ))}
                    </div>
                )}

                <button 
                    onClick={() => setIsActive(!isActive)}
                    className={`w-16 h-16 rounded-full flex items-center justify-center transition-all transform hover:scale-110 active:scale-95 shadow-lg ${isActive ? 'bg-yellow-600 hover:bg-yellow-500 text-black' : 'bg-emerald-600 hover:bg-emerald-500 text-white'}`}
                >
                    {isActive ? <Pause size={28} fill="currentColor" /> : <Play size={28} fill="currentColor" className="ml-1" />}
                </button>

                <button 
                    onClick={handleFinish}
                    className="w-16 h-16 rounded-full bg-slate-800 border-2 border-slate-700 hover:border-red-500 text-slate-400 hover:text-red-500 flex items-center justify-center transition-all hover:scale-110 active:scale-95 shadow-lg"
                >
                    <Square size={24} fill="currentColor" />
                </button>
            </div>
        </div>
    </div>
  );
};
